        )}

        {/* Vehicles Tab */}
        {activeTab === 'vehicles' && (
          <div>
            <button style={styles.addVehicleBtn} onClick={() => setShowVehicleModal(true)}>+ Add Vehicle</button>
            {vehicles.length === 0 ? <div style={styles.emptyState}>No vehicles added.</div> : vehicles.map(vehicle => (
              <div key={vehicle._id} style={styles.vehicleCard}>
                <strong>{vehicle.year} {vehicle.make} {vehicle.model}</strong>
                <div>License: {vehicle.licensePlate} | Color: {vehicle.color || 'N/A'}</div>
              </div>
            ))}
          </div>
        )}

        {/* Bookings Tab */}
        {activeTab === 'bookings' && (
          <div>
            {bookings.length === 0 ? (
              <div style={styles.emptyState}>No bookings yet.</div>
            ) : (
              bookings.map(booking => (
                <div key={booking._id} style={styles.bookingCard}>
                  <div style={styles.bookingHeader}>
                    <div>
                      <h3>{booking.serviceName}</h3>
                      <p>Provider: {booking.providerId?.businessName || booking.providerId?.firstName}</p>
                    </div>
                    <span style={getStatusBadge(booking.status)}>{booking.status}</span>
                  </div>
                  <div style={styles.bookingDetails}>
                    <span>📅 {new Date(booking.bookingDate).toLocaleDateString()}</span>
                    <span>⏰ {booking.bookingTime}</span>
                    <span>💰 ${booking.totalAmount}</span>
                  </div>
                  {(booking.status === 'completed' || booking.status === 'confirmed') && (
                    <button 
                      onClick={() => downloadInvoice(booking._id)}
                      style={{ backgroundColor: '#2563eb', color: 'white', border: 'none', padding: '8px 16px', borderRadius: '6px', cursor: 'pointer', marginTop: '10px' }}
                    >
                      📄 Download Invoice
                    </button>
                  )}
                </div>
              ))
            )}
          </div>
        )}

        {/* Payments Tab */}
        {activeTab === 'payments' && (
          <div>
            <h2>💳 Payment History</h2>
            {loadingPayments ? <div style={styles.loading}>Loading...</div> : paymentHistory.length === 0 ? <div style={styles.emptyState}>No payment history yet.</div> : paymentHistory.map(payment => (
              <div key={payment._id} style={styles.bookingCard}>
                <div style={styles.bookingHeader}>
                  <div>
                    <h3>{payment.bookingId?.serviceName}</h3>
                    <div>{new Date(payment.createdAt).toLocaleDateString()}</div>
                  </div>
                  <span style={{ backgroundColor: payment.paymentStatus === 'completed' ? '#d1fae5' : '#fef3c7', color: payment.paymentStatus === 'completed' ? '#065f46' : '#92400e', padding: '4px 12px', borderRadius: '20px' }}>
                    {payment.paymentStatus === 'completed' ? '✅ Paid' : '⏳ Pending'}
                  </span>
                </div>
                <div><strong>Amount:</strong> ${payment.amount}</div>
              </div>
            ))}
          </div>
        )}

        {/* Profile Tab */}
        {activeTab === 'profile' && (
          <div style={styles.profileContainer}>
            <h2>👤 My Profile</h2>
            <div style={styles.profileCard}>
              <img src={profile.avatar} alt="avatar" style={styles.avatarLarge} />
              <div style={styles.profileInfo}>
                <div><strong>Full Name:</strong> {profile.fullName}</div>
                <div><strong>Email:</strong> {profile.email}</div>
                <div><strong>Phone:</strong> {profile.phone}</div>
                <div><strong>Address:</strong> {profile.address || 'Not set'}</div>
                <div><strong>Member Since:</strong> {profile.memberSince}</div>
              </div>
              <button style={styles.editProfileBtn} onClick={() => {
                setEditProfileData({
                  fullName: profile.fullName,
                  email: profile.email,
                  phone: profile.phone,
                  address: profile.address
                });
                setShowProfileModal(true);
              }}>✏️ Edit Profile</button>
            </div>
          </div>
        )}

        {/* Settings Tab */}
        {activeTab === 'settings' && (
          <div style={styles.settingsContainer}>
            <h2>⚙️ Settings</h2>
            <div style={styles.settingsSection}>
              <h3>🔔 Notification Preferences</h3>
              <label style={styles.settingItem}>
                <input type="checkbox" defaultChecked /> Email Notifications
              </label>
              <label style={styles.settingItem}>
                <input type="checkbox" defaultChecked /> Push Notifications
              </label>
            </div>
            <button style={styles.saveSettingsBtn} onClick={() => toast.success('Settings saved!')}>Save Settings</button>
          </div>
        )}
      </div>

      {/* Booking Modal */}
      {showBookingModal && selectedService && (
        <div style={styles.modal}>
          <div style={styles.modalContent}>
            <h2>Book {selectedService.name}</h2>
            <p><strong>Provider:</strong> {selectedService.providerBusinessName || selectedService.providerName}</p>
            <p><strong>Price:</strong> ${selectedService.price}</p>
            <label style={styles.label}>Vehicle:</label>
            <select style={styles.input} value={bookingData.vehicleId} onChange={(e) => setBookingData({...bookingData, vehicleId: e.target.value})}>
              <option value="">Select a vehicle</option>
              {vehicles.map(v => <option key={v._id} value={v._id}>{v.year} {v.make} {v.model}</option>)}
            </select>
            <label style={styles.label}>Date:</label>
            <input type="date" style={styles.input} value={bookingData.date} onChange={(e) => setBookingData({...bookingData, date: e.target.value})} min={new Date().toISOString().split('T')[0]} />
            <label style={styles.label}>Time:</label>
            <input type="time" style={styles.input} value={bookingData.time} onChange={(e) => setBookingData({...bookingData, time: e.target.value})} />
            <label style={styles.label}>
              <input type="checkbox" checked={bookingData.isConcierge} onChange={(e) => setBookingData({...bookingData, isConcierge: e.target.checked})} /> 🚗 Concierge Service (+$20)
            </label>
            {bookingData.isConcierge && (
              <>
                <label style={styles.label}>Pickup Address:</label>
                <textarea style={styles.textarea} value={bookingData.pickupAddress} onChange={(e) => setBookingData({...bookingData, pickupAddress: e.target.value})} placeholder="Enter your pickup address" />
              </>
            )}
            <div style={styles.modalActions}>
              <button style={styles.submitBtn} onClick={createBooking}>Continue to Payment</button>
              <button style={styles.cancelBtn} onClick={() => { setShowBookingModal(false); setSelectedService(null); }}>Cancel</button>
            </div>
          </div>
        </div>
      )}

      {/* Payment Modal */}
      {showPaymentModal && pendingBooking && (
        <Elements stripe={stripePromise}>
          <PaymentModal 
            booking={pendingBooking} 
            amount={pendingBooking.totalAmount} 
            onSuccess={() => { 
              setShowPaymentModal(false); 
              toast.success('Booking confirmed!'); 
              fetchBookings(); 
              fetchPaymentHistory(); 
            }} 
            onCancel={() => { 
              setShowPaymentModal(false); 
              toast.info('Booking saved. Pay later.'); 
              fetchBookings(); 
            }} 
          />
        </Elements>
      )}

      {/* Profile Edit Modal */}
      {showProfileModal && (
        <div style={styles.modal}>
          <div style={styles.modalContent}>
            <h2>Edit Profile</h2>
            <div style={styles.formGroup}>
              <label style={styles.label}>Full Name</label>
              <input type="text" style={styles.input} value={editProfileData.fullName} onChange={(e) => setEditProfileData({...editProfileData, fullName: e.target.value})} />
            </div>
            <div style={styles.formGroup}>
              <label style={styles.label}>Email</label>
              <input type="email" style={styles.input} value={editProfileData.email} onChange={(e) => setEditProfileData({...editProfileData, email: e.target.value})} />
            </div>
            <div style={styles.formGroup}>
              <label style={styles.label}>Phone</label>
              <input type="tel" style={styles.input} value={editProfileData.phone} onChange={(e) => setEditProfileData({...editProfileData, phone: e.target.value})} />
            </div>
            <div style={styles.formGroup}>
              <label style={styles.label}>Address</label>
              <input type="text" style={styles.input} value={editProfileData.address} onChange={(e) => setEditProfileData({...editProfileData, address: e.target.value})} />
            </div>
            <div style={styles.modalActions}>
              <button style={styles.submitBtn} onClick={saveProfile}>Save Changes</button>
              <button style={styles.cancelBtn} onClick={() => setShowProfileModal(false)}>Cancel</button>
            </div>
          </div>
        </div>
      )}

      {/* Vehicle Modal */}
      {showVehicleModal && (
        <div style={styles.modal}>
          <div style={styles.modalContentSmall}>
            <h2>Add Vehicle</h2>
            <form onSubmit={addVehicle}>
              <input style={styles.input} type="text" placeholder="Make" value={newVehicle.make} onChange={(e) => setNewVehicle({...newVehicle, make: e.target.value})} required />
              <input style={styles.input} type="text" placeholder="Model" value={newVehicle.model} onChange={(e) => setNewVehicle({...newVehicle, model: e.target.value})} required />
              <input style={styles.input} type="number" placeholder="Year" value={newVehicle.year} onChange={(e) => setNewVehicle({...newVehicle, year: e.target.value})} required />
              <input style={styles.input} type="text" placeholder="License Plate" value={newVehicle.licensePlate} onChange={(e) => setNewVehicle({...newVehicle, licensePlate: e.target.value})} required />
              <input style={styles.input} type="text" placeholder="Color" value={newVehicle.color} onChange={(e) => setNewVehicle({...newVehicle, color: e.target.value})} />
              <div style={styles.modalActions}>
                <button type="submit" style={styles.submitBtn}>Save</button>
                <button type="button" style={styles.cancelBtn} onClick={() => setShowVehicleModal(false)}>Cancel</button>
              </div>
            </form>
          </div>
        </div>
      )}
    </div>
  );
}

export default CustomerDashboard;
